import { sql, type SQL } from "drizzle-orm";
import { bigint, numeric, timestamp, uuid, type PgColumn } from "drizzle-orm/pg-core";
import { v7 as uuidv7 } from "uuid";

/**
 * Column conventions from the Technical Architecture (section 2–3):
 * - UUID v7 primary keys, generated by the app (devices may create them offline).
 * - Money is bigint paise. Drizzle maps it to a JS number: exact for integers up to
 *   9,007,199,254,740,991 paise (≈ ₹90 lakh crore), far beyond a shop's figures. Only integer
 *   arithmetic is allowed on these values.
 * - Quantities are numeric(14,3) in the product's base unit, returned as strings (exact).
 * - Every table has created_at.
 */
export const id = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

export const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

export const paise = (name: string) => bigint(name, { mode: "number" });

export const quantity = (name: string) => numeric(name, { precision: 14, scale: 3 });

/** `column in ('a','b',...)` for CHECK constraints. Values are fixed literals from the schema, never user input. */
export function oneOf(column: PgColumn, values: readonly string[]): SQL {
  const list = values.map((value) => `'${value.replace(/'/g, "''")}'`).join(", ");
  return sql`${column} in (${sql.raw(list)})`;
}
